insert into public.site_settings (key, value) values ('hero', '{"eyebrow":"Prata 925 · Aço · Folheados Premium","title":"O brilho que acompanha você","subtitle":"Joias lindas e acessíveis, escolhidas com carinho para iluminar todos os seus momentos.","cta_label":"Conheça nossa coleção","cta_link":"/loja","image_url":"/demo/hero.webp","image_alt":"Colares dourados e prateados pendurados sobre cetim branco (imagem de exemplo)"}'::jsonb) on conflict (key) do nothing;
insert into public.site_settings (key, value) values ('home', '{"marquee":["Prata 925","Aço Inoxidável","Folheados Premium","Recife — PE","Atendimento pelo WhatsApp"],"featured_category_ids":[],"featured_title":"Escolhas da Dois Brilhos","bestsellers_title":"Mais amadas","new_title":"Novidades","collections_title":"Coleções em destaque","show_testimonials":true,"show_instagram":true}'::jsonb) on conflict (key) do nothing;
insert into public.site_settings (key, value) values ('about', '{"eyebrow":"Sobre nós","title":"Dois Brilhos Joias","text":"A Dois Brilhos é uma loja de joias de Recife — PE, com peças em Prata 925, Aço Inoxidável e Folheados Premium.\n\nNosso propósito é simples: joias lindas e acessíveis. O atendimento é feito de pessoa para pessoa, pelo WhatsApp, por Michael e Nicolly.","image_url":"/demo/sobre.webp","highlights":[{"title":"Prata 925","text":"Prata de lei para quem busca durabilidade."},{"title":"Aço Inoxidável","text":"Resistência para o dia a dia."},{"title":"Folheados Premium","text":"Acabamento dourado e prateado."}],"care_title":"Cuidados com suas joias","care_tips":["Evite contato com perfumes, cremes, cloro e água do mar.","Retire as peças para dormir, praticar exercícios e tomar banho.","Guarde cada joia separadamente, em local seco e protegido.","Limpe com uma flanela macia e seca após o uso."]}'::jsonb) on conflict (key) do nothing;
insert into public.site_settings (key, value) values ('contact', '{"city":"Recife — PE","email":"","hours":"","address":""}'::jsonb) on conflict (key) do nothing;
insert into public.site_settings (key, value) values ('social', '{"instagram":"https://www.instagram.com/doisbrilhos.ofc/","linktree":"https://linktr.ee/doisbrilhosjoias","tiktok":"","facebook":""}'::jsonb) on conflict (key) do nothing;
insert into public.site_settings (key, value) values ('footer', '{"tagline":"Joias lindas e acessíveis.","note":"Os pedidos feitos pelo site são finalizados pelo WhatsApp e só são confirmados após o atendimento."}'::jsonb) on conflict (key) do nothing;
insert into public.site_settings (key, value) values ('attendants', '[{"id":"michael","name":"Michael","phone":"5581998070744","active":true},{"id":"nicolly","name":"Nicolly","phone":"5581996404201","active":true}]'::jsonb) on conflict (key) do nothing;
insert into public.site_settings (key, value) values ('instagram', '{"handle":"doisbrilhos.ofc","profile_url":"https://www.instagram.com/doisbrilhos.ofc/","posts":[]}'::jsonb) on conflict (key) do nothing;
insert into public.site_settings (key, value) values ('seo', '{"title":"Dois Brilhos Joias — Prata 925, Aço e Folheados Premium","description":"Joias lindas e acessíveis em Prata 925, Aço Inoxidável e Folheados Premium. Recife — PE. Peça pelo WhatsApp.","og_image":"/og-image.jpg"}'::jsonb) on conflict (key) do nothing;
